154→// Search calls the search service to perform a hybrid search.
155→func Search(ctx context.Context, cfg Config) (*Response, error) {
156→	ctx, cancel := context.WithTimeout(ctx, apiTimeout)
157→	defer cancel()
158→
159→	serviceURL := cfg.ServiceURL
160→	if serviceURL == "" {
161→		serviceURL = DefaultServiceURL
162→	}
163→
164→	u, err := url.Parse(serviceURL)
165→	if err != nil {
166→		return nil, fmt.Errorf("parsing service URL: %w", err)
167→	}
168→	u.Path = "/search/v1/search"
169→
170→	q := u.Query()
171→	q.Set("q", cfg.Query)
172→	q.Set("repo", cfg.Owner+"/"+cfg.Repo)
173→	q.Set("types", "checkpoints")
174→	if cfg.Limit > 0 {
175→		q.Set("limit", strconv.Itoa(cfg.Limit))
176→	}
177→	if cfg.Author != "" {
178→		q.Set("author", cfg.Author)
179→	}
180→	if cfg.Date != "" {
181→		q.Set("date", cfg.Date)
182→	}
183→	if cfg.Branch != "" {
184→		q.Set("branch", cfg.Branch)
185→	}
186→	if cfg.Page > 0 {
187→		q.Set("page", strconv.Itoa(cfg.Page))
188→	}
189→	u.RawQuery = q.Encode()
190→
191→	req, err := http.NewRequestWithContext(ctx, http.MethodGet, u.String(), nil)
192→	if err != nil {
193→		return nil, fmt.Errorf("creating request: %w", err)
194→	}
195→	req.Header.Set("Authorization", "Bearer "+cfg.GitHubToken)
196→	req.Header.Set("User-Agent", "entire-cli")
197→
198→	resp, err := httpClient.Do(req)
199→	if err != nil {
200→		return nil, fmt.Errorf("calling search service: %w", err)
201→	}
202→	defer resp.Body.Close()
203→
204→	body, err := io.ReadAll(io.LimitReader(resp.Body, 1<<20))
205→	if err != nil {
206→		return nil, fmt.Errorf("reading response: %w", err)
207→	}
208→
209→	if resp.StatusCode != http.StatusOK {
210→		var errResp struct {
211→			Error string `json:"error"`
212→		}
213→		if json.Unmarshal(body, &errResp) == nil && errResp.Error != "" {
214→			return nil, fmt.Errorf("search service error (%d): %s", resp.StatusCode, errResp.Error)
215→		}
216→		return nil, fmt.Errorf("search service returned %d: %s", resp.StatusCode, string(body))
217→	}
218→
219→	var result Response
220→	if err := json.Unmarshal(body, &result); err != nil {
221→		return nil, fmt.Errorf("parsing response: %w", err)
222→	}
223→
224→	if result.Error != "" {
225→		return nil, fmt.Errorf("search service error: %s", result.Error)
226→	}
227→
228→	return &result, nil
229→}
