// truncateBody returns the response body as a string, capped at 200 bytes
// so that large HTML pages don't flood the terminal.
func truncateBody(body []byte) string {
	const maxLen = 200
	if len(body) <= maxLen {
		return string(body)
	}
	return string(body[:maxLen]) + "..."
}

