+// wrapText wraps text to the given width, breaking at word boundaries.
+// Existing newlines in the input are preserved.
+func wrapText(text string, width int) string {
+	if width <= 0 {
+		return text
+	}
+	var result strings.Builder
+	for i, paragraph := range strings.Split(text, "\n") {
+		if i > 0 {
+			result.WriteByte('\n')
+		}
+		wrapParagraph(&result, paragraph, width)
+	}
+	return result.String()
+}
+
+func wrapParagraph(b *strings.Builder, text string, width int) {
+	words := strings.Fields(text)
+	if len(words) == 0 {
+		return
+	}
+	lineLen := 0
+	for i, w := range words {
+		wLen := len(w)
+		if i == 0 {
+			b.WriteString(w)
+			lineLen = wLen
+			continue
+		}
+		if lineLen+1+wLen > width {
+			b.WriteByte('\n')
+			b.WriteString(w)
+			lineLen = wLen
+		} else {
+			b.WriteByte(' ')
+			b.WriteString(w)
+			lineLen += 1 + wLen
+		}
+	}
+}
